        // reconnectEdge preserves the old edge ID
        finalEdgeId = existing.id
        return reconnectEdge(existing, newEdge, eds as ReactFlowEdge[])
      }
      return reactFlowAddEdge(newEdge, eds as ReactFlowEdge[])
